window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0ede935d0f2d201e"]={"versions": [{"id": "FIG-0ede935d0f2d201e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1f09a6db0cc691f5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e3f2851c38b87734", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-482badc918b5d49b", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dcf9b92fcb96e16f", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b2aacc62e068c612", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8fbcee8eb44a98fb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-df75836c1b7852ed", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles Struktur- bzw. Konfigurationsdiagramm (Metamodell-Abstraktion / Containment-Darstellung).\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform, BSW-Schicht <em>System Services</em> (<code>AUTOSAR_SWS_WatchdogManager</code>, R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Veranschaulichung der Kardinalität und Parametrisierung der <em>Alive Supervision</em> innerhalb einer einzelnen <em>Supervised Entity</em> (SE). Es demonstriert die Erweiterung gegenüber Vor-R2.0-Versionen: Eine Supervised Entity ist nicht mehr auf einen globalen Alive-Zähler beschränkt, sondern kann mehrere voneinander unabhängige Kontrollpunkte (<em>Checkpoints</em>, CPs) zur zyklischen Lebendüberwachung bündeln.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Supervised Entity (<code>SE3</code> / <code>WdgMSupervisedEntity</code>):</strong>\n<ul class=\"fig-list\"><li>Repräsentiert die logische Software-Einheit auf Applikations- (SW-C Runnable) oder BSW-Ebene, deren Ausführungsfrequenz überwacht wird.\n</li><li>Hält die Checkpoints als aggregierte Kindelemente (<code>WdgMCheckpoint</code>).\n</li></ul>\n</li><li><strong>Checkpoints (<code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code> / <code>WdgMCheckpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Kardinalität: 1 … n Checkpoints pro Supervised Entity (hier n=3).\n</li><li>Jeder Checkpoint referenziert eine eigene Instanz des Konfigurationscontainers <code>WdgMAliveSupervision</code> innerhalb eines <code>WdgMMode</code>.\n</li></ul>\n</li><li><strong>Konfigurationsparameter je Checkpoint (<code>WdgMAliveSupervision</code>):</strong>\n<ul class=\"fig-list\"><li><code>WdgMExpectedAliveIndications</code> (<code>EcucIntegerParamDef</code>): Soll-Anzahl der Checkpoint-Meldungen innerhalb des Überwachungszyklus.\n</li><li><code>WdgMMinMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige negative Abweichung (Unterschreitung) der Meldungen.\n</li><li><code>WdgMMaxMargin</code> (<code>EcucIntegerParamDef</code>): Zulässige positive Abweichung (Überschreitung) der Meldungen.\n</li><li><code>WdgMSupervisionReferenceCycle</code> (<code>EcucIntegerParamDef</code>): Granularität des Auswertefensters, angegeben als Vielfaches des <code>WdgM_MainFunction</code>-Zyklus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ereigniserfassung (Asynchron / Event-getrieben):</strong>\n<ul class=\"fig-list\"><li>Die überwachte Entität meldet das Erreichen des jeweiligen Kontrollpunkts synchron über die RTE-Schnittstelle bzw. BSW-API:\n <code>WdgM_CheckpointReached(SEID=SE3, CPID=CP3_x)</code>.\n</li><li>Der WdgM inkrementiert atomar den zugehörigen Alive-Zähler des spezifischen Checkpoints (<code>CP3-1</code>, <code>CP3-2</code> oder <code>CP3-3</code>).\n</li></ul>\n</li><li><strong>Zyklische Auswertung (Synchron im WdgM-Task):</strong>\n<ul class=\"fig-list\"><li>In <code>WdgM_MainFunction()</code> wird der Referenzzyklus-Zähler des jeweiligen Checkpoints dekrementiert.\n</li><li>Bei Ablauf von <code>WdgMSupervisionReferenceCycle</code> erfolgt die Überprüfung:\n $$\\text{WdgMExpectedAliveIndications} - \\text{WdgMMinMargin} \\le \\text{AliveCounter} \\le \\text{WdgMExpectedAliveIndications} + \\text{WdgMMaxMargin}$$\n</li><li><strong>Gültig:</strong> Lokaler Status des Checkpoints bleibt <code>CORRECT</code>; der <code>AliveCounter</code> wird für den nächsten Referenzzyklus auf 0 zurückgesetzt.\n</li><li><strong>Ungültig (Verletzung der Grenzen):</strong> Lokaler Status wechselt auf <code>INCORRECT</code>. Der Fehlerzähler für Alive-Supervision (<code>WdgMFailedAliveSupervisionRefCycleTol</code>) wird inkrementiert.\n</li></ul>\n</li><li><strong>Fehlereskalation &amp; Callbacks:</strong>\n<ul class=\"fig-list\"><li>Überschreitet der Fehlertoleranz-Zähler das Limit, wechselt der Status von <code>SE3</code> von <code>WDGM_LOCAL_STATUS_OK</code> nach <code>WDGM_LOCAL_STATUS_FAILED</code> (bzw. nach Ablauf der Toleranzzyklen zu <code>WDGM_LOCAL_STATUS_EXPIRED</code>).\n</li><li>Benachrichtigung via <code>Det_ReportError()</code> (falls konfiguriert) und Produktion eines Dem-Events (<code>WDGM_E_SUPERVISION</code>).\n</li><li>Verhindert das Triggern des Watchdog-Treibers (<code>WdgIf</code> / <code>Wdg</code>) im <code>WDGM_GLOBAL_STATUS_STOPPED</code>, was zum Hardware-Reset führt.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Granulare Task-/Runnable-Überwachung:</strong> Ermöglicht die getrennte Überwachung mehrerer Runnables unterschiedlicher Periodizität innerhalb derselben SW-C/SE, ohne künstlich getrennte Supervised Entities anlegen zu müssen.\n</li><li><strong>Modusabhängigkeit:</strong> Die Parameter (<code>WdgMExpectedAliveIndications</code>, Toleranzen, Referenzzyklen) sind modespezifisch (<code>WdgMMode</code>). Bei WdgM-Moduswechseln werden die Zähler reinitialisiert; Entwickler müssen Modusübergänge timing-konform gestalten, um Fehlalarme während der Einschwingphase zu vermeiden.\n</li><li><strong>Timing-Jitter &amp; Margins:</strong> <code>WdgMMinMargin</code> und <code>WdgMMaxMargin</code> müssen Task-Jitter, OS-Scheduling-Latenzen und Interrupt-Blockierzeiten abfangen. Ein Margin von 0 ist in preemptiven Echtzeitsystemen fehleranfällig.\n</li><li><strong>Keine implizite Reihenfolge:</strong> Alive Supervision überwacht ausschließlich Frequenzen/Häufigkeiten. Eine Kontrollfluss-Reihenfolge zwischen <code>CP3-1</code>, <code>CP3-2</code> und <code>CP3-3</code> wird hierdurch <strong>nicht</strong> erzwungen (hierfür ist <em>Logical Supervision</em> mit Transitionen zwischen Checkpoints erforderlich).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0ede935d0f2d201e", "to": "FIG-1f09a6db0cc691f5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1f09a6db0cc691f5", "to": "FIG-e3f2851c38b87734", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e3f2851c38b87734", "to": "FIG-482badc918b5d49b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>CP3-1</code>, <code>CP3-2</code>, <code>CP3-3</code>: Führende Sichtbarkeitsmodifikatoren (<code>+</code>) vor den Parameternamen (<code>WdgMExpectedAliveIndications</code>, <code>WdgMMaxMargin</code>, <code>WdgMMinMargin</code>, <code>WdgMSupervisionReferenceCycle</code>) entfernt.\n</li></ul>"}, {"from": "FIG-482badc918b5d49b", "to": "FIG-dcf9b92fcb96e16f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-dcf9b92fcb96e16f", "to": "FIG-b2aacc62e068c612", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b2aacc62e068c612", "to": "FIG-8fbcee8eb44a98fb", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8fbcee8eb44a98fb", "to": "FIG-df75836c1b7852ed", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
